mapper.select:
select cra.es_id as auditId, employee.operatorUserId, employee.employeeName, employee.departmentId, employee.departmentName, cra.customer_id as customerId, c.name as customerName, cra.customer_tel as customerTel, cra.begin_time as beginTime, cra.answer_time as answerTime, cra.end_time as endTime, cra.duration from customer c straight_join mmba_call_record_audit cra force index (idx_mmba_call_customer_begin_ts) on cra.customer_id = c.id and cra.begin_timestamp between #{request.startTime} and #{request.endTime} straight_join ( select distinct su.id as operatorUserId, su.um, su.name as employeeName, sou.department_id as departmentId, sd.name as departmentName from sys_organization_user sou join sys_user su on su.id = sou.user_id left join sys_department sd on sd.id = sou.department_id where sou.enable = true and su.um is not null and su.um != '' ) employee on employee.um = cra.um where cra.direction = 0 and cra.call_type = 1 and cra.is_connected = 1 and cra.record is not null and trim(cra.record) != '' and trim(cra.record) != '[]'
and c.name like concat('%', #{request.customerName}, '%')
and cra.customer_tel like concat('%', #{request.customerTel}, '%')
and ifnull(cra.duration, 0) >= #{request.minDuration}
and ifnull(cra.duration, 0) <= #{request.maxDuration}
and employee.operatorUserId in
#{operatorUserId}
order by cra.begin_timestamp desc, cra.es_id desc
